using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace IoTSharp.EntityFrameworkCore;

/// <summary>Configures values generated by LiteDB BSON expressions during SaveChanges.</summary>
public static class LiteDBPropertyBuilderExtensions
{
    /// <summary>Evaluates a LiteDB expression on insert when the property still has its sentinel value.</summary>
    /// <typeparam name="TProperty">The property CLR type.</typeparam>
    /// <param name="builder">The property configuration.</param>
    /// <param name="expression">A scalar LiteDB BSON expression over ordinary persisted fields.</param>
    /// <returns>The property configuration.</returns>
    public static PropertyBuilder<TProperty> HasLiteDBDefaultExpression<TProperty>(this PropertyBuilder<TProperty> builder, string expression)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(expression);
        builder.HasAnnotation("LiteDB:DefaultExpression", expression);
        builder.ValueGeneratedOnAdd();
        return builder;
    }

    /// <summary>Evaluates a LiteDB expression on each insert or update and returns its value to the tracked entity.</summary>
    /// <typeparam name="TProperty">The property CLR type.</typeparam>
    /// <param name="builder">The property configuration.</param>
    /// <param name="expression">A scalar LiteDB BSON expression over ordinary persisted fields.</param>
    /// <returns>The property configuration.</returns>
    public static PropertyBuilder<TProperty> HasLiteDBComputedExpression<TProperty>(this PropertyBuilder<TProperty> builder, string expression)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(expression);
        builder.HasAnnotation("LiteDB:ComputedExpression", expression);
        builder.ValueGeneratedOnAddOrUpdate();
        return builder;
    }
}
